    "startLine": 53,
    "vcsPermalink": "https://github.com/calcom/cal.com/blob/180ede28f0bddf2738933a6e60a8e80f6116d7da/apps/api/v2/src/modules/auth/strategies/api-auth/api-auth.strategy.ts#L53-L152",
