    "startLine": 37,
    "vcsPermalink": "https://github.com/calcom/cal.com/blob/180ede28f0bddf2738933a6e60a8e80f6116d7da/apps/web/modules/bookings/views/bookings-single-view.getServerSideProps.tsx#L37-L272",
